    private Notification createGeneralPayment(Faq order, Product user, GeneralNotificationRequestDto requestDto) {
        Instant start = Instant.now();
        try {
            log.info("일반 결제 처리 시작: 주문ID={}, impUid={}",
                    order.getId(), requestDto.getImpUid());


            if (requestDto.getImpUid() == null || requestDto.getImpUid().isBlank()) {
                throw new NotificationException(NotificationErrorCode.PAYMENT_VALIDATION_FAILED,
                        "결제 ID(impUid)는 필수 항목입니다.");
            }

            GeneralNotification generalPayment = GeneralNotification.builder()
                    .impUid(requestDto.getImpUid())
                    .pgProvider(requestDto.getPgProvider())
                    .receiptUrl(requestDto.getReceiptUrl())
                    .buyerName(requestDto.getBuyerName())
                    .buyerEmail(requestDto.getBuyerEmail())
                    .paidAmount(requestDto.getPaidAmount())
                    .build();

            generalPayment.assignOrder(order);
            generalPayment.assignUser(user);
            generalPayment.updateSuccessStatus(true);
            generalPayment.updateStatus(NotificationStatus.PAID);

            GeneralNotification savedPayment = (GeneralNotification) paymentRepository.save(generalPayment);
            log.info("일반 결제 처리 완료: 주문ID={}, 결제ID={}, 상태={}",
                    order.getId(), savedPayment.getId(), savedPayment.getStatus());


            Instant end = Instant.now();
            Duration duration = Duration.between(start, end);
            log.debug("일반 결제 처리 시간: {}ms", duration.toMillis());

            return savedPayment;
        } catch (NotificationException e) {
            throw e;
        } catch (Exception e) {
            log.error("일반 결제 처리 중 예상치 못한 오류 발생: 주문ID={}, 오류={}",
                    order.getId(), e.getMessage(), e);
            throw new NotificationProcessingException("일반 결제 처리 중 오류가 발생했습니다: " + e.getMessage());
        }
    }







    private String impUid;
    private String pgProvider;
    private String receiptUrl;
    private String buyerName;
    private String buyerEmail;


    @Builder
    public GeneralNotification(String impUid, String pgProvider, String receiptUrl,
                          String buyerName, String buyerEmail, String status, double paidAmount) {
        this.impUid = impUid;
        this.pgProvider = pgProvider;
        this.receiptUrl = receiptUrl;
        this.buyerName = buyerName;
        this.buyerEmail = buyerEmail;
        this.setPaidAmount(paidAmount);
    }
    @Override
    public String getImpUid() {
        return this.impUid;
    }

